struct Node;

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The contract's `requires` already holds for every input; this guard
        // is defensive. The contract measures length in characters.
        if ctx.question.chars().count() > MAX_QUESTION_CHARS {
            return fail("question exceeds 512 characters");
        }

