            prompt.push_str("- ");
            prompt.push_str(item);
            prompt.push('\n');
        }

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(request) => {
                    if request.tool != TOOL_NAME {
                        return fail("model requested a tool outside its scope");
                    }
                    let hits = kb_read::lookup(&request.query);
                    prompt.push_str("\nLookup results for \"");
                    prompt.push_str(&request.query);
                    prompt.push_str("\":\n");
                    for hit in &hits {
                        prompt.push_str("- ");
                        prompt.push_str(hit);
                        prompt.push('\n');
                    }
                }
            }
        }

        fail("tool-call budget exhausted without a final answer")
    }
}

