const SYSTEM: &str = "You answer customer-support questions using the supplied context. \
You may call the `lookup` tool to search the knowledge base.";
const MAX_QUESTION_CHARS: usize = 512;
const MAX_ROUNDS: usize = 4;
const TOOL_NAME: &str = "lookup";
const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

struct Node;

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved set kept).
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Fetch the enrichment record for the input. The result is deliberately
/// discarded: enrichment is a side effect and must not change the node's output.
/// `fetch` returns transport failures as values, so a dead enrichment service
/// does not fail the run; a refused (out-of-allowlist) host still traps at the boundary.
fn enrich(question: &str) {
    let url = format!("{}{}", ENRICH_BASE, percent_encode(question));
    let _ = http_client::fetch(&url);
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The contract's `requires` already holds for every input; this guard
        // is defensive. The contract measures length in characters.
